8: } from '$lib/server/db/schema';
9: import type { AppConfig, ApplyMethod } from '$lib/server/config';
10: import { resolveActiveServer, serverTypeLabel } from '$lib/server/media-server';
11: import { writeKometaYaml } from '$lib/server/kometa/yaml';
12: import { availableProviders, PROVIDER_ORDER, type ProviderId } from './providers';
13: 
14: /**
15:  * Discover artwork candidates for an item across all enabled providers and persist
16:  * them (replacing any prior candidates), tagging each with its provider. A provider
17:  * that fails is skipped so the others still contribute. Returns the candidate count.
18:  */
19: export async function discoverForItem(
20: 	item: MediaItem,
21: 	config: AppConfig,
22: 	opts?: { forceRefresh?: boolean }
23: ): Promise<number> {
24: 	const providers = availableProviders(config);
25: 	const settled = await Promise.allSettled(
26: 		providers.map((p) =>
27: 			p
28: 				.discover(item, config, { forceRefresh: opts?.forceRefresh })
29: 				.then((sets) => ({ provider: p.id, sets }))
30: 		)
31: 	);
32: 
33: 	const rows = settled
34: 		.filter(
35: 			(
36: 				r
37: 			): r is PromiseFulfilledResult<{
38: 				provider: ProviderId;
39: 				sets: Awaited<ReturnType<(typeof providers)[number]['discover']>>;
40: 			}> => r.status === 'fulfilled'
41: 		)
42: 		.flatMap((r) =>
43: 			r.value.sets.flatMap((set) =>
44: 				set.candidates.map((c) => ({
45: 					mediaItemId: item.id,
46: 					provider: r.value.provider,
47: 					setId: c.setId,
48: 					setAuthor: c.setAuthor,
49: 					url: c.url,
50: 					kind: c.kind,
51: 					season: c.season,
52: 					episode: c.episode
53: 				}))
54: 			)
55: 		);
56: 
57: 	await db.delete(posterCandidates).where(eq(posterCandidates.mediaItemId, item.id));
58: 	if (rows.length) await db.insert(posterCandidates).values(rows);
59: 	await db
60: 		.update(mediaItems)
61: 		.set({ hasMediux: rows.length > 0, updatedAt: new Date() })
62: 		.where(eq(mediaItems.id, item.id));
63: 
64: 	return rows.length;
65: }
